        try c.SetLogFile(logA) { reverted1 = false; } catch { reverted1 = true; }
        try c.Initialized() {} catch { return; }
        bool reverted2;
        try c.SetLogFile(logB) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(!reverted1 && reverted2);
    }

